  // ── Legal framework ──────────────────────────────────────────
  legalFrameworkIntro: 'Oman operates a structured education framework under the Ministry of Education (MoE) that regulates the ~2,133 schools nationwide including 1,200+ private schools and kindergartens (2024 Ministry data). Oman has an established equivalency framework recognising Cambridge, IB, and American qualifications.',
  legalFramework: [
    { h: 'Ministry of Education framework',              p: 'Oman MoE regulates schools nationwide and issues equivalency certificates between IB Diploma, IGCSE/A-Level, and Omani General Education Diploma for university applications. Tasneef (MoE Office of Rating Private Schools) established 2019 but ratings remain unpublished as of 2026.' },
    { h: 'Tuition VAT-exempt',                            p: 'School tuition fees are zero-rated for VAT in Oman (5% general VAT applies since 2021 to most other services). Educational services are protected. Ancillary services (transport, uniforms via third-party suppliers) may incur VAT.' },
    { h: 'Non-citizen expat families — flexible',         p: 'Oman\'s expatriate community operates under residence permit frameworks and pursues international curriculum via authorised international schools or online providers. Omani MoE equivalency covers Cambridge, IB, and American qualifications for return-to-employment purposes.' },
    { h: 'Pre-primary and secondary — unrestricted',     p: 'Children under 6 (pre-primary) and children 12+ (secondary — Cambridge IGCSE Years 10-11, A-Level Years 12-13, IB Diploma) are unrestricted for all Omani and expat families. This is Smartious\'s core Oman delivery window.' },
  ],

